// no stray characters, no repeated unit, no unit out of largest-first order.
// The lookahead rejects '' without dropping the requirement of at least one group.
const DURATION_RE = /^(?=\d)(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

function parseDuration(input) {
  const groups = typeof input === 'string' && DURATION_RE.exec(input);
  if (!groups) throw new RangeError(`Invalid duration: ${JSON.stringify(input)}`);
